def findRedundantDirected(edges):
    n = len(edges)
    parent_of = [0] * (n + 1)
    first = second = None
    for u, v in edges:
        if parent_of[v]:
            first = [parent_of[v], v]
            second = [u, v]
        else:
            parent_of[v] = u
    uf = list(range(n + 1))

    def find(x):
        while uf[x] != x:
            uf[x] = uf[uf[x]]
            x = uf[x]
        return x

    for u, v in edges:
        if second is not None and [u, v] == second:
            continue
        ru, rv = find(u), find(v)
        if ru == rv:
            return first if second is not None else [u, v]
        uf[ru] = rv
    return second
